import ExcelJS from 'exceljs';

export const exportToExcel = (projectDetails, sections) => {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Project Details');

    // Function to apply styles to cells
    const applyStyles = (cell, style) => {
        cell.alignment = { vertical: 'middle', horizontal: 'center' }; // Center align content
        cell.font = { bold: true, size: style.fontSize || 12 }; // Default font size is 12
        cell.border = {
            top: { style: 'thin' },
            left: { style: 'thin' },
            bottom: { style: 'thin' },
            right: { style: 'thin' }
        };
        if (style.backgroundColor) {
            cell.fill = {
                type: 'pattern',
                pattern: 'solid',
                fgColor: { argb: style.backgroundColor }
            };
        }
        cell.numFmt = style.format || undefined; // Number format
        if (style.rowHeight) {
            cell.height = style.rowHeight; // Set row height
        }
        if (style.columnWidth) {
            worksheet.getColumn(cell._address.charAt(0)).width = style.columnWidth; // Set column width
        }
    };

    // Helper function to get Excel column alphabets
    const getExcelAlpha = (i) => {
        if (i <= 0) return '';
        let s = '';
        while (i > 0) {
            let rem = i % 26;
            if (rem === 0) {
                s = 'Z' + s;
                i = Math.floor(i / 26) - 1;
            } else {
                s = String.fromCharCode((rem - 1) + 'A'.charCodeAt(0)) + s;
                i = Math.floor(i / 26);
            }
        }
        return s;
    };

    // Add project details to the worksheet in columns
    worksheet.getColumn('A').values = [['Project Name']];
    worksheet.getColumn('B').values = [[projectDetails.projectName]];
    worksheet.getColumn('C').values = [['Client']];
    worksheet.getColumn('D').values = [[projectDetails.client]];
    worksheet.getColumn('E').values = [['Contractor']];
    worksheet.getColumn('F').values = [[projectDetails.contractor]];
    worksheet.getColumn('G').values = [['Consultant']];
    worksheet.getColumn('H').values = [[projectDetails.consultant]];
    worksheet.getColumn('I').values = [['Title']];
    worksheet.getColumn('J').values = [[projectDetails.title]];
    worksheet.addRow([]); // Empty row for spacing

    // Function to add sections and their data to the worksheet
    const addDataToSectionsSheet = (section, sectionIndex, startColIndex) => {
        let colIndex = startColIndex;

        // Add section name with specific style
        const sectionNameCell = worksheet.getCell(`${getExcelAlpha(colIndex)}1`);
        sectionNameCell.value = `Section Name: ${section.section_name}`;
        applyStyles(sectionNameCell, { backgroundColor: 'FFCC99', fontSize: 14, rowHeight: 20, columnWidth: 30 }); // Example color, font size, row height, and column width
        colIndex++;

        if (section.subsections) {
            section.subsections.forEach((subsection, subsectionIndex) => {
                // Add subsection name with specific style
                const subsectionNameCell = worksheet.getCell(`${getExcelAlpha(colIndex)}1`);
                subsectionNameCell.value = `Subsection Name: ${subsection.subsection_name}`;
                applyStyles(subsectionNameCell, { backgroundColor: 'FFFFCC', fontSize: 12, rowHeight: 18, columnWidth: 25 }); // Example color, font size, row height, and column width
                colIndex++;

                if (subsection.documents) {
                    subsection.documents.forEach((document) => {
                        // Add document details with specific style
                        const documentNameCell = worksheet.getCell(`${getExcelAlpha(colIndex)}1`);
                        documentNameCell.value = `Document Name: ${document.serial_number}-${document.document_name}`;
                        applyStyles(documentNameCell, { backgroundColor: 'CCEEFF', fontSize: 10, rowHeight: 16, columnWidth: 20 }); // Example color, font size, row height, and column width
                        colIndex++;

                        // Add document details in subsequent columns
                        worksheet.getColumn(getExcelAlpha(colIndex)).values.push(['Start Date', document.start_date || 'N/A']);
                        worksheet.getColumn(getExcelAlpha(colIndex + 1)).values.push(['End Date', document.end_date || 'N/A']);
                        worksheet.getColumn(getExcelAlpha(colIndex + 2)).values.push(['Status', document.status || 'N/A']);
                        worksheet.getColumn(getExcelAlpha(colIndex + 3)).values.push(['Priority', document.priority || 'N/A']);
                        worksheet.getColumn(getExcelAlpha(colIndex + 4)).values.push(['Assigned To', document.assigned_to || 'N/A']);
                        worksheet.getColumn(getExcelAlpha(colIndex + 5)).values.push(['Progress', document.progress || 'N/A']);
                        worksheet.addRow([]); // Empty row for spacing
                    });
                    colIndex += 6; // Move to the next set of columns for the next document
                }
            });
        }
        return colIndex; // Return the updated column index for the next section
    };

    // Start adding sections from Column K (11th column)
    let startColIndex = 11;

    // Iterate over sections and add their data
    if (sections) {
        sections.forEach((section, index) => {
            startColIndex = addDataToSectionsSheet(section, index, startColIndex);
        });
    }

    // Save the workbook
    workbook.xlsx.writeBuffer().then((buffer) => {
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${projectDetails.projectName}_Details.xlsx`;
        a.click();
        URL.revokeObjectURL(url);
    });
};
